import (
	"fmt"
	"regexp"
	"strings"
)

// Render translates markdown to HTML.
//
// Refactoring notes:
//
// The original implementation walked the input one byte at a time and
// carried several intertwined pieces of state (header level, list depth,
// a "seen a header" flag, ...), which made the control flow hard to
